-- Parents of translations mirror the Thai parent's translation (breadcrumbs per locale)
UPDATE pages c
JOIN pages cth ON cth.translation_group = c.translation_group AND cth.locale = 'th' AND cth.deleted_at IS NULL
JOIN pages pth ON pth.id = cth.parent_id
JOIN pages p   ON p.translation_group = pth.translation_group AND p.locale = c.locale AND p.deleted_at IS NULL
SET c.parent_id = p.id
WHERE c.locale <> 'th' AND c.parent_id IS NULL AND c.deleted_at IS NULL;

-- Organization facts for JSON-LD (verified: QUESTIONS.md) + default share image
UPDATE settings SET value = CONVERT(X'' USING utf8mb4), updated_at = NOW() WHERE setting_key = 'organization' AND deleted_at IS NULL;
